import{c as e,Q as o,j as d,m as l}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Multi-Mode Agent + Skill 設計：四模式內聯 · 自動 model 路由 · 破-4 fan-out · /loop 排程","description":"","frontmatter":{"title":"Multi-Mode Agent + Skill 設計：四模式內聯 · 自動 model 路由 · 破-4 fan-out · /loop 排程","date":"2026-06-12T00:00:00.000Z","status":"applied","branch":"claude/multi-mode-agent-design-5psvdg","method":"3-way researcher fan-out（pilot skills / agent schema / fan-out+context+report 慣例）→ The Loop 六階段設計","scope":".claude/agents/multi-mode-agent.md · .claude/skills/multi-mode-skill/SKILL.md · .claude/skills/RESOLVER.md","type":"design"},"headers":[],"relativePath":"research/reports/archive/2026-06-12-multi-mode-agent-skill-design.md","filePath":"research/reports/archive/2026-06-12-multi-mode-agent-skill-design.md","lastUpdated":1785909234000}'),a={name:"research/reports/archive/2026-06-12-multi-mode-agent-skill-design.md"};function r(i,t,n,s,c,g){return o(),d("div",null,[...t[0]||(t[0]=[l(`<h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>需求是「可 <code>/loop</code> 週期觸發、每 fire 跑 The Loop、自動選最省 model、fan-out 不受 4 限制」的自主執行單元。 交付 = <strong>一對配對產物</strong>，非單一 agent 或單一 skill：</p><ul><li><strong><code>multi-mode-skill</code></strong>（主對話 router/orchestrator）：分類任務 → 選 model/effort/mode → inline 或 spawn worker；寬任務走 dynamic workflow 破 4；內建 <code>/loop</code> 接線。</li><li><strong><code>multi-mode-agent</code></strong>（sub-agent worker）：四模式（fable/opus/sonnet/haiku）紀律 <strong>內聯</strong>，解決「SKILL 不能在 sub-agent 執行」。</li></ul><p><strong>誠實邊界</strong>：本遠端 web 環境<strong>無 <code>CronCreate</code>/<code>ScheduleWakeup</code> 排程原語</strong>（ToolSearch 三次查無），無法在此武裝週期計時器。排程須於本機 CL/桌面 app 觸發；報告交代接線與停止方式，未偽造排程。</p><h2 id="需求-→-解法對照" tabindex="-1">需求 → 解法對照 <a class="header-anchor" href="#需求-→-解法對照" aria-label="Permalink to &quot;需求 → 解法對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>需求</th><th>解法</th><th>落地位置</th></tr></thead><tbody><tr><td>1</td><td>agent 要有 4 pilot SKILL 能力（因 SKILL 無法在 sub-agent 用）</td><td>四模式核心 gate <strong>內聯</strong>到 agent body（mode 紀律表）；不引用 Skill 工具（實證：15 個既有 agent 無一在 tools 列 Skill）</td><td><code>multi-mode-agent.md</code> Mode 紀律表</td></tr><tr><td>2</td><td>每 session 用最有效率 model，200K/1M 不爆 context、不衰退</td><td>model <strong>spawn 時綁定</strong>（router 依檔案數選）；NLAH + 委派重讀 + compaction 觸發 + <code>claude-progress.json</code> checkpoint</td><td><code>multi-mode-skill.md</code> §1 §4</td></tr><tr><td>3</td><td>fan-out sub-agent 不受最多並行限制</td><td>寬任務走 <strong>dynamic workflow</strong>（runtime ≤16並行/≤1000總量，與「主對話手動 4」不同層級）；multi-mode-agent 為 worker 單元</td><td><code>multi-mode-skill.md</code> §3 + agent Fan-out 段</td></tr><tr><td>4</td><td>參考現有準則</td><td>全程接地 CLAUDE.md + 4 auto-load rules + prompt-lifecycle；frontmatter/慣例比對既有 agent/skill</td><td>全程</td></tr><tr><td>5</td><td>補不完備處</td><td>見下「補充缺口」</td><td>—</td></tr><tr><td>6</td><td>研究後出報告</td><td>本檔</td><td>—</td></tr></tbody></table><h2 id="核心架構決策-decision-log" tabindex="-1">核心架構決策（Decision-Log） <a class="header-anchor" href="#核心架構決策-decision-log" aria-label="Permalink to &quot;核心架構決策（Decision-Log）&quot;">​</a></h2><ol><li><p><strong>Pair 而非單體</strong></p><ul><li>Choice：skill(router) + agent(worker) 配對。</li><li>Rejected：① 單 agent — 無法在主對話做 skill 路由、sub-agent 無法自切 model；② 單 skill — sub-agent 無 Skill 工具（正是需求 1 的痛點）。</li><li>Reason：路由/排程是主對話職責，紀律執行是 worker 職責，職責分離。</li></ul></li><li><p><strong>model 綁定於 spawn，mode 只切紀律</strong></p><ul><li>sub-agent 無法 mid-run 換 model（且 mid-session 切 model 破 prompt cache，context-management.md 禁止）。</li><li>故「多模式」拆兩軸：<strong>model = spawn 時由 router 綁定</strong>（最佳成本）；<strong>mode（cost/quality/ceiling/frontier）= agent body 切換的紀律強度</strong>。router 負責 model↔mode 最佳配對。</li></ul></li><li><p><strong>Fan-out 破 4 = 換層級非提高上限</strong></p><ul><li>subagent-strategy.md:16 明載「4 上限僅限主對話手動委派；dynamic workflow runtime ≤16/≤1000」。兩者不同層級不衝突。</li><li>故破 4 = 寬任務改走 dynamic workflow（<code>agent()/parallel()/pipeline()</code>，每 worker 可指定 model + worktree），非去改 4 這個數字。</li></ul></li></ol><h2 id="四模式內聯紀律-需求-1-細節" tabindex="-1">四模式內聯紀律（需求 1 細節） <a class="header-anchor" href="#四模式內聯紀律-需求-1-細節" aria-label="Permalink to &quot;四模式內聯紀律（需求 1 細節）&quot;">​</a></h2><p>各 pilot 的「無法從 repo 推導的行為契約」被提煉進 agent，capability-agnostic：</p><table tabindex="0"><thead><tr><th>Mode (model)</th><th>內聯的關鍵 gate</th></tr></thead><tbody><tr><td>cost (haiku)</td><td>量化 escalation gate（≤9檔/≤300LoC stay；≥10檔/跨模組/test/≥3失敗 escalate）；&gt;30LoC 止於 explain；citation anchor 分級</td></tr><tr><td>quality (sonnet)</td><td>Forced self-review（&gt;30LoC 自審 diff；auth/payment/user-data 安全自審）；line-level source-verify <code>:LineN</code>；Decision-Log</td></tr><tr><td>ceiling (opus)</td><td>Reverse-advisor 自我 peer-review；CAR 標籤；Reasoning Sandwich（Plan→Implement→Verify）；Decision-Log ≥3 外化</td></tr><tr><td>frontier (fable)</td><td>Anti-hack 雙重驗證（自產 verdict 非證據，親跑 grep/test）；worktree <code>git diff</code> 落地檢查；evaluator 防弱化斷言；trace-first</td></tr></tbody></table><p>升級鏈：cost→quality→ceiling→frontier；frontier 失敗 ≥3 = ill-posed，停並重述（無升級路）。</p><h2 id="model-路由表-需求-2-依-model-selection-grid" tabindex="-1">Model 路由表（需求 2，依 model-selection-grid） <a class="header-anchor" href="#model-路由表-需求-2-依-model-selection-grid" aria-label="Permalink to &quot;Model 路由表（需求 2，依 model-selection-grid）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>獨立位置數 / 信號</th><th>model</th><th>effort</th><th>mode</th></tr></thead><tbody><tr><td>0–1</td><td>haiku</td><td>low</td><td>cost</td></tr><tr><td>2–5</td><td>sonnet</td><td>medium–high</td><td>quality</td></tr><tr><td>6–9</td><td>sonnet</td><td>high</td><td>quality</td></tr><tr><td>10+ / 跨模組</td><td>sonnet→opus</td><td>xhigh</td><td>ceiling</td></tr><tr><td>架構/安全設計關鍵字</td><td>opus</td><td>xhigh</td><td>ceiling</td></tr><tr><td>最難架構+長程 agentic / opus 不收斂</td><td>claude-fable-5</td><td>high</td><td>frontier</td></tr></tbody></table><p>定價錨點（per 1M in/out，2026-05-30 雙源）：Haiku $1/$5 · Sonnet $3/$15 · Opus $5/$25 · Fable $10/$50（effective ≈2.6× Opus）。Opus 僅 1.67× Sonnet → ceiling 任務不必恐懼成本。</p><h2 id="context-不爆-不衰退-需求-2" tabindex="-1">Context 不爆 / 不衰退（需求 2） <a class="header-anchor" href="#context-不爆-不衰退-需求-2" aria-label="Permalink to &quot;Context 不爆 / 不衰退（需求 2）&quot;">​</a></h2><ul><li><strong>可靠工作區</strong>：1M 名義 context 實際可靠僅 64–128K（lost-in-the-middle U 型偏差）→ 主對話只收 worker 摘要，重讀全委派。</li><li><strong>NLAH</strong>：goal 放 HEAD、最新工具輸出放 TAIL。</li><li><strong>Compaction</strong>：行為信號（迷失問句）&gt; 數字（一般 70%、長 agentic 30–35%）；compact 必用相同 system prompt+tools（否則 cache 失效）。</li><li><strong>防衰退關鍵</strong>：<code>claude-progress.json</code> 外存 goal+成功條件+進度，每 <code>/loop</code> fire 重讀（fresh context 不依賴記憶）。</li></ul><h2 id="loop-⊗-the-loop-接線-需求核心" tabindex="-1">/loop ⊗ The Loop 接線（需求核心） <a class="header-anchor" href="#loop-⊗-the-loop-接線-需求核心" aria-label="Permalink to &quot;/loop ⊗ The Loop 接線（需求核心）&quot;">​</a></h2><p>本機 CLI：<code>/loop 30m multi-mode &lt;task&gt;</code>。每 fire 全新 context，故 prompt 自包含： OBSERVE 讀 progress → router 選 model/mode → inline/spawn worker 跑六階段 → 主對話親跑確定性 gate 升 verified → RECORD 更新 progress；委派 <code>self-escalate</code> 判收斂，<code>converged &amp;&amp; confidence≥0.85</code> → 建議 <code>CronDelete &lt;job-id&gt;</code> 停 loop。recurring task 7 天自動過期。</p><h2 id="補充缺口-需求-5" tabindex="-1">補充缺口（需求 5） <a class="header-anchor" href="#補充缺口-需求-5" aria-label="Permalink to &quot;補充缺口（需求 5）&quot;">​</a></h2><p>設計過程發現並補上的不完備處：</p><ol><li><strong>缺 sub-agent 可攜的紀律載體</strong> — 既有 4 pilot 全是 SKILL，沒有任何 sub-agent 能在委派狀態套用其紀律。multi-mode-agent 填此空缺。</li><li><strong>缺自動 model router</strong> — model-selection-grid 是「人讀的決策表」，無自動執行體。multi-mode-skill §1 將其轉成可執行路由。</li><li><strong>缺破-4 fan-out 的明確姿勢</strong> — 規則散在 subagent-strategy:16 + harness-meta GOTCHAS，無單一入口。本設計集中為 §3。</li><li><strong><code>refs/</code> 路徑漂移</strong>（回報，未修）：subagent-strategy.md 引用 <code>refs/error-handling.md</code>、core.md 引用 <code>refs/harness-loop.md</code>，實際在 <code>.claude/refs/</code>。屬任務外，記錄不順手改（commit 原子性）。</li></ol><h2 id="驗證-test" tabindex="-1">驗證（TEST） <a class="header-anchor" href="#驗證-test" aria-label="Permalink to &quot;驗證（TEST）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bash scripts/healthcheck.sh | tail -4</span></span>
<span class="line"><span>======================================</span></span>
<span class="line"><span> 統計結果：PASS: 128  WARN: 2  FAIL: 0</span></span>
<span class="line"><span>======================================</span></span>
<span class="line"><span>健康檢查完成，有 2 個警告項目。</span></span></code></pre></div><ul><li>FAIL: 0（修復了「RESOLVER.md 未登錄 multi-mode-skill」一項）。</li><li>2 WARN 為既有（MCP servers 空），與本變更無關。</li><li>frontmatter 比對：agent 用 <code>name/description/tools/model/permissionMode/isolation</code>（match implementer）；skill 用 <code>name/description/version/roster-trigger/roster-domain/allowed-tools/review-by</code>（match haiku-pilot）。</li></ul><h2 id="限制與後續" tabindex="-1">限制與後續 <a class="header-anchor" href="#限制與後續" aria-label="Permalink to &quot;限制與後續&quot;">​</a></h2><ul><li><strong>排程不可用於本環境</strong>：CronCreate/ScheduleWakeup 僅本機/桌面；遠端 web 退化單輪。已誠實標注，未偽造。</li><li><strong>dynamic workflow 可用性未驗</strong>：為 Opus 4.8 runtime 功能，依 plan/mode（Max/Team/Enterprise 預設；Pro 需 /config）。採信 worker verdict 前主對話須機械 grep 重驗。</li><li>後續可選：寫 eval（eval-designer）量化「router 選對 model 的命中率」作為回歸閘門。</li></ul>`,27)])])}const h=e(a,[["render",r]]);export{m as __pageData,h as default};
